WITH src AS (SELECT * FROM products WHERE brand <> 'Globex'), launch_month_summary AS (SELECT DATE_TRUNC('MONTH', launch_date) AS launch_month, YEAR(launch_date) AS launch_year, MAX(stock_qty) AS max_stock_qty, MAX(price) - MIN(price) AS price_range FROM src GROUP BY DATE_TRUNC('MONTH', launch_date), YEAR(launch_date)) SELECT launch_month, launch_year, price_range FROM launch_month_summary ORDER BY launch_month DESC
